package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sync"
	"time"
)

// Node state
type Node struct {
	id    string
	values map[int]int // msg_id -> value
	mu    sync.Mutex
}

var (
	node *Node
	nodes []*Node
	// topology from init
	nodeId, allIds string
	topicMu = &sync.RWMutex{}

	// Track broadcast values at each node for deduplication and forwarding
	broadcastValueMap map[string]int // "node_id": msg_id -> value

	// Track which nodes have received which broadcasts (for tracking progress)
	receivedValues map[string][]int // "node_id": []msg_ids that have been fully received

	topology map[string][]string
)

func newNode(id string, allNodeIds []string) *Node {
	n := &Node{id: id, values: make(map[int]int)}
	nodes = append(nodes, n)
	return n
}

func (n *Node) AddValue(msgId int, val int) {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.values[msgId] = val
}

func (n *Node) GetValue(msgId int) (int, bool) {
	n.mu.Lock()
	defer n.mu.Unlock()
	val, ok := n.values[msgId]
	return val, ok
}

func (n *Node) GetAllValues() []int {
	n.mu.Lock()
	defer n.mu.Unlock()
	result := make([]int, 0, len(n.values))
	for _, v := range n.values {
		result = append(result, v)
	}
	return result
}

// Global state
var globalValueMap map[int][]int // msg_id -> list of nodes that have received it

func init() {
	globalValueMap = make(map[int][]int)
	go func() {
		ticker := time.NewTicker(10 * time.Millisecond)
		for range ticker.C {
			time.Sleep(200 * time.Millisecond) // Wait for messages to arrive
		}
	}()
}

func (n *Node) Broadcast(msgId int, val int) bool {
	n.AddValue(msgId, val)

	// Track globally which nodes have this value
	globalValueMap[msgId] = append(globalValueMap[msgId], n.id)

	// Start propagation via neighbors
	go n.propagate(msgId, val)
	return true
}

func (n *Node) propagate(msgId int, val int) {
	n.values[msgId] = val // Ensure we have it

	// Find nodes that don't have this value yet and forward to them
	for _, neighborId := range n.topology {
		if has, ok := getValue(neighborId, msgId); !ok {
			sendTo(n.id, neighborId, "msg", map[string]int{
				"msg_id":    msgId,
				"value":      val,
			})
		}
	}
}

func (n *Node) propagateAll(msgIds []int, vals map[int]int) {
	for _, mid := range msgIds {
		val := vals[mid]
		go n.propagate(mid, val)
	}
}

func getValue(neighborId string, msgId int) (bool, int) {
	// Check if we have this value at the neighbor node
	if len(allIds) > 0 && neighborId == allIds[0] {
		return true, node.values[msgId]
	}
	return false, 0
}

func (n *Node) Send(to string, typ string, body interface{}) bool {
	msg := []byte("{}")
	err := json.NewEncoder(os.Stdout).Encode(map[string]interface{}{
		"src":   n.id,
		"dest":  to,
		"type":  typ,
		"body":  body,
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "Send error: %v\n", err)
		return false
	}
	time.Sleep(10 * time.Millisecond)
	return true
}

func (n *Node) SendTo(to string, msgId int) bool {
	msg := map[string]interface{}{
		"msg_id": msgId,
		"value":   n.values[msgId],
	}
	if err := json.NewEncoder(os.Stdout).Encode(msg); err != nil {
		fmt.Fprintf(os.Stderr, "SendTo error: %v\n", err)
		return false
	}
	time.Sleep(10 * time.Millisecond)
	return true
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var nodeMsgId int
	var broadcastMsgId map[int]int = make(map[int]int)

	// Track broadcast values - a value needs to go to all nodes that haven't received it
	broadcastValues := make(map[int]map[int]int) // msg_id -> {node_id: val}
	nodeToValue := make(map[string]int) // node_id -> value we just got

	// Store topology from the init command
	_ = nodeId
	_ = allIds
	_ = topicMu

	// Process topology message first if present
	topicReceived := false
	for scanner.Scan() {
		line := scanner.Text()
		if line == "init" {
			continue
		}
		if len(nodeId) > 0 { // Already received init with our ID
			continue
		}

		var msg interface{}
		json.Unmarshal([]byte(line), &msg)
		msgMap := msg.(map[string]interface{})
		typ, _ := msgMap["type"].(string)
		if typ == "topology" {
			topology = msgMap["topology"].(map[string][]string)
			topicReceived = true
			continue
		}
		if typ == "broadcast" {
			msgId, _ := msgMap["msg_id"].(float64)
			val, _ := msgMap["message"].(float64)
			broadcastMsgId[msgId] = val
			broadcastValues[0] = make(map[int]int)
			nodeToValue[node.id] = 0
		}
	}

	for _, mid := range broadcastMsgId {
		if len(mid) == 0 {
			continue
		}
		val, ok := node.values[mid]
		if !ok {
			val = int(broadcastMsgId[mid])
		}
		nodeToValue[node.id] = val
	}

	var broadcastMsgId2 []int
	for _, mid := range broadcastMsgId {
		broadcastMsgId2 = append(broadcastMsgId2, mid)
	}

	// Process messages from stdin
	go func() {
		for scanner.Scan() {
			line := scanner.Text()
			var msg interface{}
			json.Unmarshal([]byte(line), &msg)
			msgMap := msg.(map[string]interface{})
			typ := msgMap["type"].(string)

			switch typ {
			case "broadcast":
				msgId, _ := msgMap["msg_id"].(float64)
				val, _ := msgMap["message"].(float64)

				if broadcastMsgId[msgId] != 0 {
					broadcastValues[msgId] = make(map[int]int)
				}

				node.Broadcast(int(msgId), int(val))
			case "read":
				msgId, _ := msgMap["msg_id"].(float64)
				values := node.GetAllValues()

				result := make([]int, len(values))
				for i, v := range values {
					result[i] = v
				}

				reply := map[string]interface{}{
					"in_reply_to": int(msgId),
					"messages":    result,
				}

				if err := json.NewEncoder(os.Stdout).Encode(reply); err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				}
			case "topology":
				topology = msgMap["topology"].(map[string][]string)
				topicReceived = true
			default:
				continue
			}
		}
	}()

	for scanner.Scan() {
		line := scanner.Text()
		if line == "init" {
			var initMsg map[string]interface{}
			json.Unmarshal([]byte(line), &initMsg)
			nodeId = initMsg["node_id"].(string)
			allIds = fmt.Sprintf("%s", allIds)

			// Setup topology
			topicMu.Lock()
			if topicReceived {
				for n := range nodes {
					nodes[n].id = nodeId
					nodes[n].topology = topology
				}
			}
			break
		}

		var msg interface{}
		json.Unmarshal([]byte(line), &msg)
		msgMap := msg.(map[string]interface{})
		typ := msgMap["type"].(string)

		switch typ {
		case "broadcast":
			msgId, _ := msgMap["msg_id"].(float64)
			val, _ := msgMap["message"].(float64)

			nodeToValue[node.id] = val

			node.Broadcast(int(msgId), int(val))
		case "read":
			msgId, _ := msgMap["msg_id"].(float64)
			values := node.GetAllValues()

			result := make([]int, len(values))
			for i, v := range values {
				result[i] = v
			}

			reply := map[string]interface{}{
				"in_reply_to": int(msgId),
				"messages":    result,
			}

			if err := json.NewEncoder(os.Stdout).Encode(reply); err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			}
		case "topology":
			topology = msgMap["topology"].(map[string][]string)
			topicReceived = true

			// Process topology - create forwarding structure
			for _, nid := range nodes {
				nid.topology = topology
			}

			// Propagate broadcast values through the network
			for mid, val := range broadcastValues {
				node.propagateAll([]int{mid}, val)
			}
		default:
			continue
		}
	}
}

func send(from, to string, typ string, body interface{}) error {
	msg := map[string]interface{}{
		"src": from,
		"dest": to,
		"type":  typ,
		"body": body,
	}
	return json.NewEncoder(os.Stdout).Encode(msg)
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sync"
	"time"
)

// Message types between nodes
type Msg struct {
	Type  string            `json:"type"`
	Body  map[string]int    `json:"body"`
}

// BroadcastRequest comes from clients
type BroadcastReq struct {
	Type     string      `json:"type"`
	MsgId    int         `json:"msg_id"`
	Message  int         `json:"message"`
	InReplyTo int        `json:"in_reply_to,omitempty"`
}

// BroadcastReply to client
type BroadcastResp struct {
	Type       string   `json:"type"`
	InReplyTo  int      `json:"in_reply_to"`
	Received   []int    `json:"received"` // msg_ids that reached this node
}

// ReadResponse comes from clients
type ReadResp struct {
	Type     string        `json:"type"`
	InReplyTo int          `json:"in_reply_to"`
	Messages []int         `json:"messages"` // values broadcast to this node
}

// Read request from clients
type ReadReq struct {
	Type   string `json:"type"`
	MsgId  int    `json:"msg_id"`
}

// TopologyRequest comes once at start
type TopologyReq struct {
	Type     string      `json:"type"`
	MsgId    int         `json:"msg_id"`
	Topology map[string][]string `json:"topology"`
	InReplyTo int          `json:"in_reply_to,omitempty"`
}

// AllNodeValuesResp from clients - lists all msg_ids this node has received
type AllNodeValuesResp struct {
	Type       string     `json:"type"`
	InReplyTo  int        `json:"in_reply_to"`
	Messages   []int      `json:"messages"` // all msg_ids known to this node
}

// Node state
type NodeState struct {
	id          string
	myId        bool
	valueMap    map[int]int       // msg_id -> value
	allMsgIds   map[int]struct{}  // msg_ids we've seen (for tracking)
	valuesByNode map[string][]int // node_id -> list of msg_ids received from it

	mu sync.Mutex
}

var (
	globalState struct {
		myId string
		nodeCount int
		allIds  []string
		topicMu sync.RWMutex
	}
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	var myNode *NodeState

	// Track broadcast values per message_id: msg_id -> value
	broadcastValues := make(map[int]int)

	// Track for each client read operation which nodes have received it
	// We'll track which broadcast ops are "complete" (all nodes have them)
	broadcastOps struct {
		mu      sync.Mutex
		opToVal map[int]int // msg_id -> value
	}
	broadcastOps.mu.Lock()
	broadcastOps.opToVal = make(map[int]int)
	broadcastOps.mu.Unlock()

	typeId := false
	nodeIdsReceived := false

	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()

		if line == "init" {
			continue
		}

		var msg interface{}
		json.Unmarshal([]byte(line), &msg)
		msgMap, ok := msg.(map[string]interface{})
		if !ok {
			fmt.Fprintf(os.Stderr, "Error unmarshaling: %s\n", line)
			os.Exit(1)
		}

		typ := msgMap["type"].(string)

		switch typ {
		case "init":
			myId = msgMap["node_id"].(string)
			globalState.myId = myId
			globalState.nodeCount = len(msgMap["all_node_ids"].([]interface{}))
			globalState.allIds = make([]string, globalState.nodeCount)
			allNodes := msgMap["all_node_ids"].([]interface{})
			for i, id := range allNodes {
				globalState.allIds[i] = id.(string)
			}
			nodeIdsReceived = true
			myNode = &NodeState{
				id:   myId,
				valueMap: make(map[int]int),
				allMsgIds: make(map[int]struct{}),
				valuesByNode: make(map[string][]int),
			}

		case "topology":
			topicReq := msgMap.(map[string]interface{})
			topologyReqId, _ := topicReq["msg_id"].(float64)
			msgId := int(topicReqId)
			topology := topicReq["topology"].(map[string][]string)

			// Store the topology for each node - create a forwarding structure
			for _, nid := range globalState.allIds {
				nidMu := &sync.RWMutex{} // For each node's own topology access
				_ = nidMu
			}

			// We'll track per-node topology separately
			// Store: nodeId -> neighborIds
			nodeToNeighbors := make(map[string][]string)
			for n, ns := range topology {
				nodeToNeighbors[n] = ns
			}

		case "broadcast":
			var req BroadcastReq
			json.Unmarshal([]byte(line), &req)
			msgId := req.MsgId
			val := req.Message

			if broadcastOps.mu.Lock() {
				broadcastOps.opToVal[msgId] = val
			} else {
				fmt.Fprintf(os.Stderr, "Lock failure\n")
				os.Exit(1)
			}
			broadcastOps.mu.Unlock()

			// Store the value at this node
			nodeAddValue(myNode.id, msgId, val)

			// Track which messages we've received from which nodes for forwarding
			if myNode.valuesByNode[myId] == nil {
				myNode.valuesByNode[myId] = make([]int, 0)
			}
			if _, exists := nodeAddValue(myNode.id, msgId, val); !exists {
				// We have this value - broadcast to others who don't have it
				go myNode.propagateBroadcast(msgId, val)
			}

		case "read":
			var req ReadReq
			json.Unmarshal([]byte(line), &req)
			msgId := req.MsgId

			// Get all msg_ids this node knows about
			msgs := collectAllMsgIds(myNode.id)

			reply := map[string]interface{}{
				"in_reply_to":  int(msgId),
				"messages":     msgs,
			}

			if err := json.NewEncoder(os.Stdout).Encode(reply); err != nil {
				fmt.Fprintf(os.Stderr, "Error encoding: %v\n", err)
			}

		default:
			fmt.Fprintf(os.Stderr, "Unknown type: %s\n", typ)
		}

		if typ == "broadcast_ok" {
			msg := map[string]interface{}{
				"type":     "broadcast_ok",
				"in_reply_to": int(req.MsgId),
			}
			json.NewEncoder(os.Stdout).Encode(msg)
		}
	}

	closeStderrLine(fmt.Sprintf("Node %s: finished\n", myId))
}

// collectAllMsgIds returns all msg_ids we know about, in any order
func collectAllMsgIds(nodeId string) []int {
	node := getNodeState(nodeId)
	result := make([]int, 0, len(node.allMsgIds))
	for mid := range node.allMsgIds {
		result = append(result, mid)
	}
	return result
}

// nodeAddValue adds a msg_id -> value mapping at the given node
func nodeAddValue(nodeId string, msgId int, val int) bool {
	node := getNodeState(nodeId)

	if _, exists := node.valueMap[msgId]; !exists {
		// Store the value at this node
		node.valueMap[msgId] = val

		// Track that we've seen this message id
		node.allMsgIds[msgId] = struct{}{}

		// Add it to the valuesByNode map if not present
		if _, exists := node.valuesByNode[nodeId]; !exists {
			node.valuesByNode[nodeId] = []int{msgId}
		} else {
			node.valuesByNode[nodeId] = append(node.valuesByNode[nodeId], msgId)
		}

		return true
	}
	return false
}

// getNodeState gets the node state for the given id, creating it if needed
func getNodeState(nodeId string) *NodeState {
	if myNode != nil && nodeId == myNode.id {
		return myNode
	}

	for _, n := range nodes {
		if n.id == nodeId {
			return &n.state
		}
	}

	// Create a new node if needed
	newN := &NodeState{
		id:        nodeId,
		valueMap:  make(map[int]int),
		allMsgIds: make(map[int]struct{}),
		valuesByNode: make(map[string][]int),
	}
	nodes = append(nodes, *newN)
	return newN
}

func (n *NodeState) propagateBroadcast(msgId int, val int) {
	// Keep the value locally
	n.valueMap[msgId] = val

	// Find nodes that don't have this value and forward to them
	n.propagateToOtherNodes(msgId, val)
}

func (n *NodeState) propagateToOtherNodes(msgId int, val int) {
	// Use the topology if available, otherwise use all other nodes
	if len(n.topology) > 0 {
		for _, neighbor := range n.topology {
			if _, exists := n.valueMap[msgId]; !exists {
				continue
			}

			nid := getNodeState(neighbor)

			if nid != nil && msgId >= 0 {
				// Send to this node
				_ = sendMsg(n.id, neighbor, "msg", map[string]int{
					"msg_id":    msgId,
					"value":      val,
				})
			}
		}
	}
}

func (n *NodeState) sendAll(msgIds []int, vals map[int]int) {
	for _, mid := range msgIds {
		val := vals[mid]
		n.propagateToOtherNodes(mid, val)
	}
}

