package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sync"
)

// Global state shared across nodes
type Node struct {
	id        string
	allNodeId int
	nodeCount int
}

var (
	nodes []*Node
	myId  int
	topology map[string][]string
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	// Track broadcast values: msg_id -> value (for our own node)
	valuesByMsgID := make(map[int]int)

	// Track which nodes have received which messages
	// This is needed to know what to send
	nodeToHaveMsg struct {
		mu  sync.RWMutex
		has map[string][]int // nodeId -> []msgIds we have
	}
	nodeToHaveMsg.mu.Lock()
	nodeToHaveMsg.has = make(map[string][]int)
	nodeToHaveMsg.mu.Unlock()

	var msgId int

	// Handle init message first
	line := scanner.Text()
	if line == "init" {
		// Find our node ID from all the messages
		for scanner.Scan() {
			line = scanner.Text()
		}

		// Check if we have init message with our node info
		var initMsg interface{}
		json.Unmarshal([]byte(line), &initMsg)
		initMap := initMsg.(map[string]interface{})
		myId = int(initMap["node_id"].(float64))

		// Initialize global state
		for _, msg := range initMap {
			val := json.Marshal(msg)
		}

		// Create a new node for each ID in the cluster
		for i := 0; i < int(initMap["total_nodes"].(float64)); i++ {
			nodes = append(nodes, &Node{id: fmt.Sprintf("node%d", i), allNodeId: i})
		}

		// Find our node and get topology
		for _, n := range nodes {
			if n.allNodeId == myId {
				myNode = n
				break
			}
		}

		// Get topology from init message if available
		topology = make(map[string][]string)

		line = scanner.Text()
		var topoMsg interface{}
		json.Unmarshal([]byte(line), &topoMsg)
		topoMap := topoMsg.(map[string]interface{})
		if topologyData, ok := topoMap["topology"].(map[string]json.RawMessage); ok {
			for k, v := range topologyData {
				var nodesList []int
				json.Unmarshal([]byte(v), &nodesList)
				topology[k] = nodesList
			}
		}
	}

	line = scanner.Text()
	if line == "init" {
		return
	}

	// Process all messages
	for scanner.Scan() {
		line = scanner.Text()

		var msg interface{}
		json.Unmarshal([]byte(line), &msg)
		msgMap, ok := msg.(map[string]interface{})
		if !ok {
			continue
		}

		typ := msgMap["type"].(string)

		switch typ {
		case "topology":
			// Store topology for this node
			msgId = int(msgMap["msg_id"].(float64))
			topologyData, ok := msgMap["topology"].(map[string]json.RawMessage)
			if ok {
				for k, v := range topologyData {
					var nodesList []int
					json.Unmarshal([]byte(v), &nodesList)
					topology[k] = nodesList
				}
			}

		case "broadcast":
			msgId = int(msgMap["msg_id"].(float64))
			val := int(msgMap["message"].(float64))

			// Store value at this node
			valuesByMsgID[msgId] = val

			// Check which other nodes don't have this value yet and forward to them
			for _, neighborId := range topology[myId.(string)] {
				sendTo(neighborId.(string), "msg", map[string]int{
					"msg_id":    msgId,
					"value":      val,
				})
			}

		case "read":
			msgId = int(msgMap["msg_id"].(float64))

			// Get all msg_ids we know about
			result := make([]int, 0, len(valuesByMsgID))
			for mid := range valuesByMsgID {
				result = append(result, mid)
			}

			reply := map[string]interface{}{
				"in_reply_to":  int(msgId),
				"messages":     result,
			}

			json.NewEncoder(os.Stdout).Encode(reply)

		case "broadcast_ok":
			msg := map[string]interface{}{
				"type":     "broadcast_ok",
				"in_reply_to": int(msgId),
			}
			json.NewEncoder(os.Stdout).Encode(msg)

		default:
			fmt.Fprintf(os.Stderr, "Unknown type: %s\n", typ)
		}
	}

	fmt.Fprintf(os.Stderr, "Node %d finished\n", myId)
}

var myNode *Node = nil

// sendTo sends a message to another node via the maelstrom network
func sendTo(neighborId string, typ string, body map[string]interface{}) {
	msg := map[string]interface{}{
		"src":   myNode.id,
		"dest":  neighborId,
		"type":  typ,
		"body":  body,
	}

	json.NewEncoder(os.Stdout).Encode(msg)
}

// Helper to process init message properly
func getInitMsgData(line string) map[string]interface{} {
	var msg interface{}
	json.Unmarshal([]byte(line), &msg)
	return msg.(map[string]interface{})
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
)

// Message between nodes
type NodeMsg struct {
	Type  string            `json:"type"`
	Body  json.RawMessage   `json:"body,omitempty"`
	Meta  map[string]int    `json:"-"`
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	var myId int = -1
	var nodeCount int = 0
	var allNodeIds []int
	topology map[int][]int

	// Process init message first - find our ID and get the topology
	for scanner.Scan() {
		line := scanner.Text()
		if line == "init" {
			continue
		}

		var msg interface{}
		json.Unmarshal([]byte(line), &msg)
		msgMap, ok := msg.(map[string]interface{})
		if !ok {
			continue
		}

		typ := msgMap["type"].(string)
		if typ == "init" {
			allNodeIds = make([]int, 0)
			if arr, ok := msgMap["all_node_ids"].([]interface{}); ok {
				for _, v := range arr {
					allNodeIds = append(allNodeIds, int(v.(float64)))
				}
			}

			var nodeCountInt float64
			nodeCount = int(nodeCountInt)

			if i, ok := msgMap["node_id"].(float64); ok {
				myId = int(i)
			}

		} else if typ == "topology" {
			topologyData, ok := msgMap["topology"].(map[string]interface{})
			if ok {
				for k, v := range topologyData {
					var neighbors []int
					json.Unmarshal([]byte(v.(json.RawMessage)), &neighbors)
					topology[k] = neighbors
				}
			}
		}
	}

	if myId < 0 {
		fmt.Fprintf(os.Stderr, "Error: did not receive init message\n")
		os.Exit(1)
	}

	// Create a simple map for the topology - use allNodeIds as IDs (0 to N-1)
	nodeToNeighbors := make(map[int][]int)
	if len(topology) > 0 {
		for n := range nodeToNeighbors {
			for _, nid := range allNodeIds {
				if _, ok := topology[nid]; ok {
					// Find which node this entry maps to (it should be myId)
					break
				}
			}
		}
	}

	// Track broadcast values at each node
	valuesByMsgID := make(map[int]int)

	// We'll track which messages we've "handled" vs which are new broadcasts
	// Since each broadcast comes exactly once, we can just track seen msg_ids

	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()

		var msg interface{}
		json.Unmarshal([]byte(line), &msg)
		msgMap, ok := msg.(map[string]interface{})
		if !ok {
			continue
		}

		typ := msgMap["type"].(string)

		switch typ {
		case "topology":
			// Store topology - we'll use it for forwarding
			topologyData, ok := msgMap["topology"].(map[string]interface{})
			if ok {
				for k, v := range topologyData {
					var neighbors []int
					json.Unmarshal([]byte(v.(json.RawMessage)), &neighbors)
					// Map key to the actual node index (it should be myId's index if it's our node)
					neighborIndex := k.(int) // Assume keys are already integer IDs
					nodeToNeighbors[neighborIndex] = neighbors
				}
			}

		case "broadcast":
			msgId := int(msgMap["msg_id"].(float64))
			val := int(msgMap["message"].(float64))

			valuesByMsgID[msgId] = val

			// Get the neighbor list for our node
			var neighbors []int
			if nid, ok := myId.(int); ok {
				var nList []int
				json.Unmarshal([]byte(topology[nid].(json.RawMessage)), &nList)
				neighbors = nList
			}

			// Send to all neighbors who might need this value
			for _, neighbor := range neighbors {
				sendTo(neighbor, "msg", map[string]int{
					"msg_id":    msgId,
					"value":      val,
				})
			}

		case "read":
			msgId := int(msgMap["msg_id"].(float64))

			// Return all msg_ids we know about (the values stored at this node)
			result := make([]int, 0, len(valuesByMsgID))
			for mid := range valuesByMsgID {
				result = append(result, mid)
			}

			reply := map[string]interface{}{
				"in_reply_to":  msgId,
				"messages":     result,
			}

			json.NewEncoder(os.Stdout).Encode(reply)

		case "broadcast_ok":
			msgId := int(msgMap["msg_id"].(float64))
			reply := map[string]interface{}{
				"type":       "broadcast_ok",
				"in_reply_to": msgId,
			}

			json.NewEncoder(os.Stdout).Encode(reply)

		case "rpc", "send":
			// Handle inter-node communication
			msgId := int(msgMap["msg_id"].(float64))
			val := int(msgMap["value"].(float64))

			valuesByMsgID[msgId] = val

			// Forward to all our neighbors
			var nList []int
			json.Unmarshal([]byte(topology[myId].(json.RawMessage)), &nList)

			for _, neighbor := range nList {
				sendTo(neighbor, "msg", map[string]int{
					"msg_id":    msgId,
					"value":      val,
				})
			}

		default:
			// Handle any other message type (e.g., log messages from maelstrom)
		}
	}

	fmt.Fprintf(os.Stderr, "Node %d processed %d broadcast operations\n", myId, len(valuesByMsgID))
}

func sendTo(neighbor int, typ string, body map[string]interface{}) {
	msg := map[string]interface{}{
		"src":   myId,
		"dest":  neighbor,
		"type":  typ,
		"body":  json.Marshal(body),
	}

	json.NewEncoder(os.Stdout).Encode(msg)
}

// Process init properly to get all the node info we need
func processInit(line string) map[string]interface{} {
	var msg interface{}
	json.Unmarshal([]byte(line), &msg)
	return msg.(map[string]interface{})
}

package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
)

// Node represents a node in the cluster
type Node struct {
	id int // 0-indexed, matches all_node_ids from init
}

var nodes []*Node
	var myId int = -1
	topology map[int][]int

	var seenMsgIds map[int]bool // msg_ids we know about
	valuesAtNode map[int]int    // msg_id -> value at this node

func main() {
	// Read initial topology and identify our node
	for scanner := bufio.NewScanner(os.Stdin); scanner.Scan(); {
		line := scanner.Text()

		var msg interface{}
		json.Unmarshal([]byte(line), &msg)
		msgMap, ok := msg.(map[string]interface{})
		if !ok {
			continue
		}

		typ := msgMap["type"].(string)

		if typ == "init" {
			// Parse init message to get our ID and all node IDs
			allNodeIds := make([]int, 0)

			totalNodes := int(msgMap["total_nodes"].(float64))

			if i := float64(0); ok {
				myId = int(i)
			}

			// Store our node ID and topology
			var nList []int
			if arr, ok := msgMap["all_node_ids"].([]interface{}); ok {
				for _, v := range arr {
					allNodeIds = append(allNodeIds, int(v.(float64)))
				}
			}

			tlMap := msgMap["topology"].(map[string]interface{})
			topology = make(map[int][]int)

			for k, v := range tlMap {
				var nl []int
				json.Unmarshal([]byte(v.(json.RawMessage)), &nl)
				topology[k] = nl
			}

			return
		} else if typ == "topology" {
			tlMap := msgMap["topology"].(map[string]interface{})
			for k, v := range tlMap {
				var nl []int
				json.Unmarshal([]byte(v.(json.RawMessage)), &nl)
				topology[k] = nl
			}
		}
	}

	// Initialize tracking
	seenMsgIds = make(map[int]bool)
	valuesAtNode = make(map[int]int)

	for _, n := range nodes {
		if int(n.id) == myId {
			break
		}
	}

	scanner := bufio.NewScanner(os.Stdin)

	for scanner.Scan() {
		line := scanner.Text()

		var msg interface{}
		json.Unmarshal([]byte(line), &msg)
		msgMap, ok := msg.(map[string]interface{})
		if !ok {
			continue
		}

		typ := msgMap["type"].(string)

		switch typ {
		case "topology":
			tlMap := msgMap["topology"].(map[string]interface{})
			for k, v := range tlMap {
				var nl []int
				json.Unmarshal([]byte(v.(json.RawMessage)), &nl)
				topology[k] = nl
			}

		case "broadcast":
			msgId := int(msgMap["msg_id"].(float64))
			val := int(msgMap["message"].(float64))

			seenMsgIds[msgId] = true
			valuesAtNode[msgId] = val

			// Forward to all neighbors (this is a simple flooding approach)
			for _, nId := range topology[myId] {
				sendMsg(nId, "msg", map[string]int{
					"msg_id":    msgId,
					"value":      val,
				})
			}

		case "read":
			msgId := int(msgMap["msg_id"].(float64))

			// Return all msg_ids we know (those that have been broadcast)
			result := make([]int, 0)
			for mid := range seenMsgIds {
				if val, ok := valuesAtNode[mid]; ok {
					result = append(result, mid)
				}
			}

			reply := map[string]interface{}{
				"in_reply_to":  msgId,
				"messages":     result,
			}

			json.NewEncoder(os.Stdout).Encode(reply)

		case "broadcast_ok":
			msgId := int(msgMap["msg_id"].(float64))
			reply := map[string]interface{}{
				"type":       "broadcast_ok",
				"in_reply_to": msgId,
			}

			json.NewEncoder(os.Stdout).Encode(reply)

		default:
		}
	}

	fmt.Fprintf(os.Stderr, "Node %d finished\n", myId)
}

func sendTo(nId int, typ string, body map[string]interface{}) {
	msg := map[string]interface{}{
		"src":   myId,
		"dest":  nId,
		"type":  typ,
		"body":  json.Marshal(body),
	}

	json.NewEncoder(os.Stdout).Encode(msg)
}

// Use allNodeIds as the node identifiers (0 to N-1)
func processTopology(line string) map[string]interface{} {
	var msg interface{}
	json.Unmarshal([]byte(line), &msg)
	return msg.(map[string]interface{})
}
